from pathlib import Path

ROOT = Path('.')

def read(path):
    return (ROOT / path).read_text(encoding='utf-8')

def write(path, text):
    (ROOT / path).parent.mkdir(parents=True, exist_ok=True)
    (ROOT / path).write_text(text, encoding='utf-8')

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'REPLACEMENT {label!r} expected once, found {count}')
    return text.replace(old, new, 1)

def replace_between(text, start, end, new_middle, label):
    i = text.find(start)
    if i < 0:
        raise SystemExit(f'BETWEEN start missing: {label}')
    j = text.find(end, i + len(start))
    if j < 0:
        raise SystemExit(f'BETWEEN end missing: {label}')
    return text[:i + len(start)] + new_middle + text[j:]

